import { useState, useEffect } from 'react';
import { Table, Button } from 'react-bootstrap';
import { useSearchParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

interface Game {
  id: number;
  status: string;
  maps: { id: number; name: string }[];
}

const GameConstructor = () => {
  const [searchParams] = useSearchParams();
  const gameId = searchParams.get('game');
  const [game, setGame] = useState<Game | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (gameId) {
      axios.get(`/api/games/${gameId}`)
        .then(res => setGame(res.data))
        .catch(err => console.error(err));
    }
  }, [gameId]);

  if (!game) return <div>Loading...</div>;

  return (
    <div>
      <h2>Game Constructor (Status: {game.status})</h2>
      <Table striped bordered hover>
        <thead>
          <tr>
            <th>Map</th>
            {game.status === 'draft' && <th>Actions</th>}
          </tr>
        </thead>
        <tbody>
          {game.maps.map(map => (
            <tr key={map.id}>
              <td>{map.name}</td>
              {game.status === 'draft' && (
                <td>
                  <Button
                    variant="danger"
                    onClick={() => axios.delete(`/api/games/${game.id}/remove-map/${map.id}`)}
                  >
                    Remove
                  </Button>
                </td>
              )}
            </tr>
          ))}
        </tbody>
      </Table>
      {game.status === 'draft' && (
        <Button onClick={() => axios.put(`/api/games/form/${game.id}`).then(() => navigate('/games'))}>
          Form Game
        </Button>
      )}
      <Button onClick={() => navigate('/games')}>Back to Games</Button>
    </div>
  );
};

export default GameConstructor;
